contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _min, uint _dep, uint _am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (_dep)); require(_dep <= 1000000000000000000000000000000);
        require(address(this).balance >= _dep);
        require(_dep >= _am);
        require(_dep >= _min);

        c.SetMinSum(_min); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        c.Deposit{value: _dep}(); if (__ESBMC_reverted()) return;

        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.Collect(_am); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(
            (!reverted && balAfter + _am == balBefore) ||
            (reverted && balAfter == balBefore)
        );
    }

    receive() external payable {}
}

