contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 _min, uint256 _dep, uint256 _am) internal {
        _dep = bound(_dep, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= _dep);
        vm.assume(_dep >= _am);
        vm.assume(_dep >= _min);
        try c.SetMinSum(_min) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: _dep}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        bool reverted;
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balAfter;
        try c.balances(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        assertTrue((!reverted && balAfter + _am == balBefore) ||
            (reverted && balAfter == balBefore));
    }

    function testFuzz_run(uint256 _min, uint256 _dep, uint256 _am) public {
        _run(_min, _dep, _am);
    }

    receive() external payable {}
}
